style:
/* 显式选择的列表样式接管模板默认圆点装饰，避免 data-list 被模板 ul/li 规则盖掉。 */
.tw-qihang.resume-paper .paper-rich ul[data-list],
.tw-qihang.resume-paper .paper-rich ol[data-list] {
  margin: 0.5mm 0 0;
  padding-left: 1.2em;
}
.tw-qihang.resume-paper .paper-rich ul[data-list] > li,
.tw-qihang.resume-paper .paper-rich ol[data-list] > li {
  padding-left: 0;
  position: relative;
}
.tw-qihang.resume-paper .paper-rich ul[data-list] > li::before,
.tw-qihang.resume-paper .paper-rich ol[data-list] > li::before {
  content: none;
  width: auto;
  height: auto;
  border-radius: 0;
  background: none;
  border: 0;
  box-shadow: none;
  left: auto;
  right: auto;
  top: auto;
  margin: 0;
  padding: 0;
}
.tw-qihang.resume-paper .paper-rich ul[data-list="disc"] { list-style-type: disc; }
.tw-qihang.resume-paper .paper-rich ul[data-list="circle"] { list-style-type: circle; }
.tw-qihang.resume-paper .paper-rich ul[data-list="square"] { list-style-type: square; }
.tw-qihang.resume-paper .paper-rich ul[data-list="square-open"] { list-style-type: "□   "; }
.tw-qihang.resume-paper .paper-rich ul[data-list="square-open"] > li::marker { font-size: 0.62em; }
.tw-qihang.resume-paper .paper-rich ul[data-list="diamond"] { list-style-type: "◆   "; }
.tw-qihang.resume-paper .paper-rich ul[data-list="diamond-open"] { list-style-type: "◇   "; }
.tw-qihang.resume-paper .paper-rich ul[data-list="diamond"] > li::marker,
.tw-qihang.resume-paper .paper-rich ul[data-list="diamond-open"] > li::marker { font-size: 0.62em; }
.tw-qihang.resume-paper .paper-rich ul[data-list="triangle"] { list-style-type: "▸   "; }
.tw-qihang.resume-paper .paper-rich ul[data-list="check"] { list-style-type: "✓   "; }
.tw-qihang.resume-paper .paper-rich ul[data-list="check"] > li::marker { font-size: 0.75em; }
.tw-qihang.resume-paper .paper-rich ol[data-list="decimal"] { list-style-type: decimal; }
.tw-qihang.resume-paper .paper-rich ol[data-list="cjk"] { list-style-type: miniwho-cjk; }
.tw-qihang.resume-paper .paper-rich ol[data-list="roman-upper"] { list-style-type: upper-roman; }
.tw-qihang.resume-paper .paper-rich ol[data-list="roman-lower"] { list-style-type: lower-roman; }
.tw-qihang.resume-paper .paper-rich ol[data-list="alpha-upper"] { list-style-type: upper-alpha; }
.tw-qihang.resume-paper .paper-rich ol[data-list="alpha-lower"] { list-style-type: lower-alpha; }
.tw-qihang.resume-paper .paper-rich ol[data-list="paren"] { padding-left: 1.2em; list-style: none; counter-reset: paren-item; }
.tw-qihang.resume-paper .paper-rich ol[data-list="paren"] > li { position: relative; counter-increment: paren-item; }
.tw-qihang.resume-paper .paper-rich ol[data-list="paren"] > li::before {
  content: "（" counter(paren-item) "）";
  position: absolute;
  right: calc(100% + 0.08em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.62em;
  line-height: 1.7;
  white-space: nowrap;
}
.tw-qihang.resume-paper .paper-rich ol[data-list="paren-right"] { padding-left: 1.2em; list-style: none; counter-reset: paren-right-item; }
.tw-qihang.resume-paper .paper-rich ol[data-list="paren-right"] > li { position: relative; counter-increment: paren-right-item; }
.tw-qihang.resume-paper .paper-rich ol[data-list="paren-right"] > li::before {
  content: counter(paren-right-item) ")";
  position: absolute;
  right: calc(100% + 0.12em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
